const resultItems = $input.all();
const taskItems = $('Wait For Directory Setup').all();
const outputs = [];
const manifest = [];
const prompts = [];

function collectUrls(value, urls = []) {
  if (!value) return urls;
  if (typeof value === 'string') {
    if (/^https?:\/\//i.test(value)) urls.push(value);
    return urls;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectUrls(item, urls);
    return urls;
  }
  if (typeof value === 'object') {
    for (const key of ['url', 'image_url', 'imageUrl', 'image', 'remoteUrl']) {
      if (value[key]) collectUrls(value[key], urls);
    }
    for (const key of ['data', 'images', 'image_urls', 'urls', 'result', 'output', 'rawResponse']) {
      if (value[key]) collectUrls(value[key], urls);
    }
  }
  return urls;
}

function unique(values) {
  return [...new Set(values.filter(Boolean))];
}

function text(value) {
  return value === undefined || value === null ? '' : String(value);
}

function readError(value) {
  if (!value || typeof value !== 'object') return '';
  return text(
    value.errorMessage ||
    value.message ||
    value.error?.message ||
    value.error?.errorMessage ||
    value.rawResponse?.errorMessage ||
    value.rawResponse?.error?.message ||
    ''
  ).trim();
}

function buildReferenceImages(task) {
  const viewImages = Array.isArray(task.viewImages)
    ? task.viewImages.filter(Boolean)
    : [task.viewImageAdd1, task.viewImageAdd2, task.viewImageAdd3, task.viewImageAdd4, task.viewImageAdd5].filter(Boolean);
  return {
    image1: task.viewImageAdd1 || '',
    image2: task.viewImageAdd2 || '',
    image3: task.viewImageAdd3 || '',
    image4: task.viewImageAdd4 || '',
    image5: task.viewImageAdd5 || '',
    viewImages,
    viewImageMeta: Array.isArray(task.viewImageMeta) ? task.viewImageMeta : [],
    imageCount: Number.isFinite(Number(task.imageCount)) ? Number(task.imageCount) : viewImages.length,
    infoFileName: task.infoFileName || '',
    infoFilePath: task.infoFilePath || '',
  };
}

function pushTextFile({ task, type, folderPath, fileName, contentText, mimeType }) {
  outputs.push({
    json: {
      type,
      fileKind: 'text',
      fileUrl: '',
      contentText: text(contentText),
      folderPath,
      fileName,
      mimeType,
      taskIndex: task?.taskIndex,
      sceneKey: task?.sceneKey,
      title: task?.title,
      titleDescription: task?.titleDescription,
      productAppearance: task?.productAppearance,
      localPath: `${folderPath}/${fileName}`,
    },
  });
}

for (let i = 0; i < taskItems.length; i += 1) {
  const task = taskItems[i]?.json || {};
  const response = resultItems[i]?.json || null;
  const imageRecords = [];
  const prompt = text(task.prompt).trim();
  const negativePrompt = text(task.negativePrompt).trim();
  let status = 'success';
  let error = '';

  if (!prompt) {
    status = 'failed';
    error = '缺少 S011 子工作流返回的图生图提示词 prompt';
  }

  const promptText = [
    '正向提示词：',
    prompt,
    '',
    '反向提示词：',
    negativePrompt,
  ].join('\n');

  pushTextFile({
    task,
    type: 'prompt',
    folderPath: task.taskDir,
    fileName: task.promptFileName || `${task.sceneKey || 'scene'}-图生图提示词.txt`,
    contentText: promptText,
    mimeType: 'text/plain; charset=utf-8',
  });

  prompts.push({
    taskIndex: task.taskIndex,
    sceneKey: task.sceneKey,
    sceneTitle: task.sceneTitle,
    title: task.title,
    titleDescription: task.titleDescription,
    scenePrompt: task.scenePrompt,
    productAppearance: task.productAppearance,
    targetPlatform: task.targetPlatform,
    targetMarket: task.targetMarket,
    ratio: task.ratio,
    referenceImages: buildReferenceImages(task),
    promptFile: task.promptFilePath,
    productDetailFile: task.productDetailFilePath,
    productDetailFileName: task.productDetailFileName,
    prompt,
    negativePrompt,
  });

  if (task.dryRun) {
    status = status === 'failed' ? status : 'dry-run';
  } else if (status !== 'failed') {
    if (!response) {
      status = 'failed';
      error = 'S003 子工作流未返回结果';
    } else {
      const urls = unique(collectUrls(response)).slice(0, 4);
      const responseError = readError(response);
      if (response.ok === false && urls.length > 0) {
        status = 'partial';
        error = responseError || 'S003 标记失败，但返回了可下载图片 URL';
      } else if (response.ok === false) {
        status = 'failed';
        error = responseError || 'S003 子工作流生图失败';
      } else if (!urls.length) {
        status = 'failed';
        error = responseError || 'S003 子工作流返回结果中没有可下载图片 URL';
      }

      for (let n = 0; n < urls.length; n += 1) {
        const remoteUrl = urls[n];
        const imageNo = String(n + 1).padStart(2, '0');
        const fileName = `${task.sceneKey}-${imageNo}.png`;
        const localPath = `${task.taskDir}/${fileName}`;
        imageRecords.push({
          imageNo: n + 1,
          fileName,
          remoteUrl,
          localPath,
          status: 'pending-download',
        });
        outputs.push({
          json: {
            type: 'image',
            fileKind: 'image',
            fileUrl: remoteUrl,
            contentText: '',
            folderPath: task.taskDir,
            fileName,
            mimeType: 'image/png',
            taskIndex: task.taskIndex,
            sceneKey: task.sceneKey,
            imageNo: n + 1,
            remoteUrl,
            localPath,
          },
        });
      }
    }
  }

  manifest.push({
    workflowId: task.workflowId,
    SKU: task.SKU,
    productName: task.productName,
    variants: task.variants,
    productDescription: task.productDescription,
    productAppearance: task.productAppearance,
    sellingPoints: task.sellingPoints,
    targetPlatform: task.targetPlatform,
    targetMarket: task.targetMarket,
    ratio: task.ratio,
    timestamp: task.timestamp,
    rootOutputDir: task.rootOutputDir,
    taskIndex: task.taskIndex,
    sceneKey: task.sceneKey,
    sceneTitle: task.sceneTitle,
    title: task.title,
    titleDescription: task.titleDescription,
    scenePrompt: task.scenePrompt,
    referenceImages: buildReferenceImages(task),
    taskDir: task.taskDir,
    promptFile: task.promptFilePath,
    productDetailFile: task.productDetailFilePath,
    productDetailFileName: task.productDetailFileName,
    prompt,
    negativePrompt,
    imageCount: imageRecords.length,
    images: imageRecords,
    status,
    error,
    rawResponse: response,
  });
}

const rootOutputDir = taskItems[0]?.json?.rootOutputDir || resultItems[0]?.json?.rootOutputDir || '';
const firstTask = taskItems[0]?.json || {};
const detailContent = text(firstTask.productDetailDescription).trim();
if (detailContent) {
  pushTextFile({
    task: firstTask,
    type: 'product-detail',
    folderPath: rootOutputDir,
    fileName: firstTask.productDetailFileName || `01-${text(firstTask.productName).trim() || 'product'}-${text(firstTask.Language).trim() || '俄文'}-详情描述.txt`,
    contentText: detailContent,
    mimeType: 'text/plain; charset=utf-8',
  });
}
if (typeof firstTask.SKU !== 'string' || !/^\d{7}$/.test(firstTask.SKU.trim())) throw new Error('输出任务缺少合法 String SKU。');
if (typeof firstTask.productName !== 'string' || !firstTask.productName.trim()) throw new Error('输出任务缺少合法 String productName。');
if (typeof firstTask.variants !== 'string' || !firstTask.variants.trim()) throw new Error('输出任务缺少合法 String variants。');
pushTextFile({
  task: firstTask,
  type: 'task-context',
  folderPath: rootOutputDir,
  fileName: 'task-context.json',
  contentText: JSON.stringify({
    schemaVersion: 1,
    workflowCode: 'E003',
    SKU: firstTask.SKU.trim(),
    productName: firstTask.productName.trim(),
    variants: firstTask.variants.trim(),
    ...(firstTask.variantId ? { variantId: String(firstTask.variantId) } : {}),
    ...(firstTask.sourceSubmissionId ? { sourceSubmissionId: String(firstTask.sourceSubmissionId) } : {}),
    n8nExecutionId: String($execution.id || ''),
  }, null, 2),
  mimeType: 'application/json; charset=utf-8',
});
pushTextFile({
  task: taskItems[0]?.json || {},
  type: 'manifest',
  folderPath: rootOutputDir,
  fileName: 'manifest.json',
  contentText: JSON.stringify(manifest, null, 2),
  mimeType: 'application/json; charset=utf-8',
});
pushTextFile({
  task: taskItems[0]?.json || {},
  type: 'prompts',
  folderPath: rootOutputDir,
  fileName: 'prompts.json',
  contentText: JSON.stringify(prompts, null, 2),
  mimeType: 'application/json; charset=utf-8',
});

return outputs;

const sourceInput = $('Attach SiliconFlow Image URLs').first().json || {};
const sceneResult = $input.first().json || {};

const productDetailDescription = extractProductDetailDescription(sceneResult.messageContent ?? sceneResult.chatResponse).trim();
if (!productDetailDescription) {
  throw new Error('S008 未返回 messageContent，无法保存俄文详情描述');
}

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function extractProductDetailDescription(value) {
  if (value === undefined || value === null) return '';

  if (typeof value === 'object' && !Array.isArray(value)) {
    for (const key of ['messageContent', 'chatResponse', 'content', 'text']) {
      if (value[key] !== undefined && value[key] !== null) {
        return extractProductDetailDescription(value[key]);
      }
    }
    return JSON.stringify(value);
  }

  const raw = String(value).trim();
  if (!raw) return '';

  if ((raw.startsWith('{') && raw.endsWith('}')) || (raw.startsWith('[') && raw.endsWith(']'))) {
    try {
      return extractProductDetailDescription(JSON.parse(raw));
    } catch (error) {
      return raw;
    }
  }

  return raw;
}

function requiredText(name, value) {
  const result = text(value);
  if (!result) {
    throw new Error(`缺少必填输入字段: ${name}`);
  }
  return result;
}

function requiredIdentityString(name, value) {
  if (typeof value !== 'string') throw new Error(`n8n_setParameter_xxx.json 的 ${name} 必须是 String。`);
  const result = value.trim();
  if (!result) throw new Error(`n8n_setParameter_xxx.json 的 ${name} 不能为空。`);
  return result;
}

function normalizeRatio(value) {
  return requiredText('ratio', value)
    .replace(/[：﹕︰]/g, ':')
    .replace(/\s*:\s*/g, ':')
    .replace(/\s+/g, '');
}

function trimTrailingSlash(value) {
  return text(value).replace(/[\\/]+$/g, '');
}

function sanitizePathPart(value) {
  return requiredText('pathPart', value)
    .replace(/[<>:"|?*\x00-\x1F]/g, '-')
    .replace(/[\\/]+/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}

function makeTimestamp() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
}

function toBoolean(value, defaultValue = false) {
  if (value === undefined || value === null || value === '') return defaultValue;

  if (typeof value === 'boolean') return value;

  const normalized = String(value).trim().toLowerCase();

  if (['true', '1', 'yes', 'y'].includes(normalized)) return true;
  if (['false', '0', 'no', 'n'].includes(normalized)) return false;

  return defaultValue;
}

const SKU = requiredIdentityString('SKU', sourceInput.SKU);
if (!/^\d{7}$/.test(SKU)) throw new Error('n8n_setParameter_xxx.json 的 SKU 必须是保留前导零的 7 位数字。');
const productName = requiredIdentityString('productName', sourceInput.productName);
const variants = requiredIdentityString('variants', sourceInput.variants);
const productDescription = text(sourceInput.productDescription);
const productAppearance = text(sceneResult.productAppearance) || text(sourceInput.productAppearance) || productDescription;

const targetPlatform = requiredText('targetPlatform', sourceInput.targetPlatform).toUpperCase();
const Country = text(sourceInput.Country || sourceInput.country);
const Language = text(sourceInput.Language || sourceInput.language) || '俄文';
const styleDirection = text(sourceInput.styleDirection);
const targetMarket = text(sceneResult.targetMarket) || text(sourceInput.targetMarket);
const ratio = normalizeRatio(sourceInput.ratio);

const outputConfig = $('setParameter').first().json || {};
const configuredBaseOutputDir = trimTrailingSlash(requiredText('setParameter.baseOutputDir', outputConfig.baseOutputDir));
const downloadFatherFolder = text(sourceInput.downloadFatherFolder);
const baseOutputDirOriginal = trimTrailingSlash(downloadFatherFolder || configuredBaseOutputDir);
const baseOutputDirWindows = '';
const baseOutputDir = baseOutputDirOriginal;

const timestamp = makeTimestamp();
const executionId = String($execution.id || '').trim();
if (!/^\d+$/.test(executionId)) throw new Error('当前工作流 executionId 无效。');
const rootOutputDir = `${baseOutputDir}/${SKU}-${sanitizePathPart(productName)}-${executionId}`;

const productDetailFileName = `01-${sanitizePathPart(productName)}-${sanitizePathPart(Language)}-详情描述.txt`;
const productDetailFilePath = `${rootOutputDir}/${productDetailFileName}`;

const maxImagesPerTask = Number.isFinite(Number(sourceInput.maxImagesPerTask))
  ? Math.max(1, Math.min(4, Number(sourceInput.maxImagesPerTask)))
  : 4;

const dryRun = toBoolean(sourceInput.dryRun, false);

const titleLength = sourceInput.titleLength;
const titleDescriptionLength = sourceInput.titleDescriptionLength;

const viewImageAdd1 = requiredText('viewImageAdd1', sourceInput.viewImageAdd1);
const viewImageAdd2 = requiredText('viewImageAdd2', sourceInput.viewImageAdd2);
const viewImageAdd3 = requiredText('viewImageAdd3', sourceInput.viewImageAdd3);
const viewImageAdd4 = text(sourceInput.viewImageAdd4);
const viewImageAdd5 = text(sourceInput.viewImageAdd5);

const viewImages = Array.isArray(sourceInput.viewImages)
  ? sourceInput.viewImages.filter(Boolean).map((value) => String(value).trim())
  : [viewImageAdd1, viewImageAdd2, viewImageAdd3, viewImageAdd4, viewImageAdd5].filter(Boolean);

const imageCount = Number.isFinite(Number(sourceInput.imageCount))
  ? Number(sourceInput.imageCount)
  : viewImages.length;

const viewImageMeta = Array.isArray(sourceInput.viewImageMeta)
  ? sourceInput.viewImageMeta
  : [];

const sellingPoints = Array.isArray(sceneResult.sellingPoints)
  ? sceneResult.sellingPoints
  : (Array.isArray(sourceInput.sellingPoints) ? sourceInput.sellingPoints : []);

const sceneKeys = [
  '01-main',
  '02-selling-point',
  '03-selling-point',
  '04-selling-point',
  '05-lifestyle',
  '06-scene',
  '07-lifestyle'
];

const outputs = [];

for (let index = 0; index < 7; index += 1) {
  const sceneNumber = String(index + 1).padStart(2, '0');
  const sceneObj = sceneResult[`scenePrompt${sceneNumber}`];

  if (!sceneObj || typeof sceneObj !== 'object' || Array.isArray(sceneObj)) {
    throw new Error(`S013 返回缺少对象字段: scenePrompt${sceneNumber}`);
  }

  const scenePrompt = requiredText(`scenePrompt${sceneNumber}.prompt`, sceneObj.prompt);

  const taskIndex = index + 1;
  const sceneKey = sceneKeys[index] || `${sceneNumber}-scene`;

  /**
   * 修改说明：
   *
   * 父工作流不再判断当前场景是否为细节展示场景或特写场景。
   * 不再根据 prompt 关键词清空 title 和 titleDescription。
   *
   * 所有场景均直接保留 S013 返回的：
   * - title
   * - titleDescription
   *
   * 如果 S013 返回空字符串，则保持空字符串。
   * 如果 S013 返回了标题和描述，则完整保留。
   */
  const title = text(sceneObj.title);
  const titleDescription = text(sceneObj.titleDescription);

  const taskDir = `${rootOutputDir}/第${taskIndex}组-${timestamp}`;
  const promptFileName = `${sceneKey}-图生图提示词.txt`;

  outputs.push({
    json: {
      workflowId: 'iaWVJzc3LMoDNaWF',

      SKU,
      productName,
      variants,
      n8nExecutionId: executionId,
      productDescription,
      productAppearance,
      sellingPoints,

      targetPlatform,
      Country,
      Language,
      targetMarket,
      styleDirection,
      ratio,

      maxImagesPerTask,
      dryRun,

      titleLength,
      titleDescriptionLength,
      titleLenth: titleLength,
      titleDescriptionLenth: titleDescriptionLength,

      viewImageAdd1,
      viewImageAdd2,
      viewImageAdd3,
      viewImageAdd4,
      viewImageAdd5,
      viewImages,
      imageCount,
      viewImageMeta,

      infoFileName: sourceInput.infoFileName || '',
      infoFilePath: sourceInput.infoFilePath || '',
      infoFileExtension: sourceInput.infoFileExtension || '',
      folderPath: sourceInput.folderPath || '',
      globPath: sourceInput.globPath || '',

      inputWarnings: Array.isArray(sourceInput.warnings) ? sourceInput.warnings : [],

      baseOutputDir,
      baseOutputDirOriginal,
      baseOutputDirWindows,
      rootOutputDir,
      timestamp,

      taskIndex,
      sceneIndex: taskIndex,
      sceneKey,

      // 为兼容下游字段保留，但父工作流不再判断细节场景。
      isDetailScene: false,

      sceneTitle: title,
      scenePrompt,
      title,
      titleDescription,
      scenePromptObj: sceneObj,

      taskDir,
      promptFileName,
      promptFilePath: `${taskDir}/${promptFileName}`,

      productDetailDescription,
      productDetailFileName,
      productDetailFilePath
    },
    pairedItem: {
      item: 0
    }
  });
}

return outputs;

const items = $input.all();

function cleanPath(value) {
  return String(value ?? '').trim().replace(/\\/g, '/').replace(/\/+$/g, '');
}

const dirs = [...new Set(
  items
    .flatMap((item) => [item.json.rootOutputDir, item.json.taskDir])
    .map(cleanPath)
    .filter(Boolean)
)];

if (!dirs.length) {
  throw new Error('没有可创建的输出目录：rootOutputDir/taskDir 均为空');
}

return [{
  json: {
    directoryCount: dirs.length,
    directories: dirs,
  },
}];

const fs = require('fs');
const path = require('path');

const items = $input.all();
if (items.length !== 1) {
  throw new Error(`Create Output Directories expects exactly 1 item, received ${items.length}.`);
}

const sourceDirs = items[0]?.json?.directories;
if (!Array.isArray(sourceDirs) || sourceDirs.length < 1) {
  throw new Error('directories must be a non-empty array');
}

const directories = [...new Set(sourceDirs.map((value, index) => {
  if (typeof value !== 'string' || !value.trim()) {
    throw new Error(`directories[${index}] must be a non-empty string`);
  }
  return path.normalize(value.trim());
}))];

for (const directory of directories) {
  fs.mkdirSync(directory, { recursive: true });
  if (!fs.statSync(directory).isDirectory()) {
    throw new Error(`Output path exists but is not a directory: ${directory}`);
  }
}

const result = { ok: true, created: directories.length, dirs: directories };
return [{
  json: {
    ...result,
    stdout: `${JSON.stringify(result)}\n`,
    stderr: '',
    exitCode: 0,
  },
}];

const items = $input.all();
const batchItems = items
  .map((item) => item.json || {})
  .filter((job) => job.folderPath && job.fileName && (job.fileUrl || Object.prototype.hasOwnProperty.call(job, 'contentText')))
  .map((job) => ({ ...job }));

if (!batchItems.length) {
  throw new Error('No download jobs produced by Download Data Prepare');
}

return [{
  json: {
    batchItems,
    concurrency: 8,
    totalJobs: batchItems.length,
    imageJobs: batchItems.filter((job) => job.fileUrl).length,
    textJobs: batchItems.filter((job) => !job.fileUrl).length,
  },
}];

const items = $input.all();
const expectedTaskCount = 7;

if (items.length !== expectedTaskCount) {
  throw new Error(
    'Prepare S003 Batch Input: expected ' + expectedTaskCount +
    ' prompt tasks, received ' + items.length + '.'
  );
}

const seenTaskIndexes = new Set();
const batchItems = items.map((item, position) => {
  const task = item.json || {};
  const taskIndex = Number(task.taskIndex);
  const prompt = String(task.prompt ?? '').trim();

  if (!Number.isInteger(taskIndex) || taskIndex < 1 || taskIndex > expectedTaskCount) {
    throw new Error(
      'Prepare S003 Batch Input: invalid taskIndex at item ' +
      (position + 1) + ': ' + String(task.taskIndex)
    );
  }

  if (seenTaskIndexes.has(taskIndex)) {
    throw new Error('Prepare S003 Batch Input: duplicate taskIndex ' + taskIndex + '.');
  }
  seenTaskIndexes.add(taskIndex);

  if (!prompt) {
    throw new Error('Prepare S003 Batch Input: taskIndex ' + taskIndex + ' is missing prompt.');
  }

  return {
    ...task,
    taskIndex,
    prompt,
    negativePrompt: String(task.negativePrompt ?? '').trim(),
  };
});

const missingTaskIndexes = Array.from(
  { length: expectedTaskCount },
  (_, index) => index + 1
).filter((taskIndex) => !seenTaskIndexes.has(taskIndex));

if (missingTaskIndexes.length) {
  throw new Error(
    'Prepare S003 Batch Input: missing taskIndex value(s): ' +
    missingTaskIndexes.join(', ') + '.'
  );
}

batchItems.sort((left, right) => left.taskIndex - right.taskIndex);

return [{
  json: {
    batchItems,
    generationConcurrency: 7,
    rootOutputDir: batchItems[0].rootOutputDir || '',
    productName: batchItems[0].productName || '',
    taskCount: batchItems.length,
  },
}];

