function __buildHiddenCommand(executable, args) {
  const __isWin = __useWindowsHiddenCommand();
  const __tempRoot = __isWin ? '__MERCHROUTE_TEMP_DIR__' : '/tmp';
  const dir = __hiddenPath.join(__tempRoot, 'n8n-hidden-command-specs');
  __hiddenFs.mkdirSync(dir, { recursive: true });
  const specPath = __hiddenPath.join(dir, 'cmd-' + Date.now() + '-' + Math.random().toString(36).slice(2, 10) + '.json');
  const spec = { executable: String(executable), args: args.map((arg) => String(arg ?? '')), createdAt: new Date().toISOString(), version: 'n8n-hidden-cli-v1' };
  __hiddenFs.writeFileSync(specPath, JSON.stringify(spec), 'utf8');
  const psScript = __HIDDEN_PS_TEMPLATE.replace('__SPEC_PATH_B64__', __hiddenB64Utf8(specPath));
  return 'powershell.exe -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -OutputFormat Text -EncodedCommand ' + Buffer.from(psScript, 'utf16le').toString('base64');
}
function __buildNodeCommand(args) {
  const normalizedArgs = args.map((arg) => String(arg ?? ''));
  if (__useWindowsHiddenCommand()) return __buildHiddenCommand('node', normalizedArgs);
  return ['node', ...normalizedArgs.map(__hiddenShQuote)].join(' ');
}
function __buildNodeEvalCommand(scriptBase64, scriptArgs = []) {
  return __buildNodeCommand(['-e', "eval(Buffer.from(process.argv[1],'base64').toString('utf8'))", scriptBase64, ...scriptArgs.map((arg) => String(arg ?? ''))]);
}
function __buildNodeGzipEvalCommand(scriptBase64, scriptArgs = []) {
  return __buildNodeCommand(['-e', "eval(require('zlib').gunzipSync(Buffer.from(process.argv[1],'base64')).toString('utf8'))", scriptBase64, ...scriptArgs.map((arg) => String(arg ?? ''))]);
}

const items = $input.all();

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function positiveInteger(value, fallback) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) && numberValue > 0 ? Math.floor(numberValue) : fallback;
}

function isWindowsPath(value) {
  const candidate = text(value);
  return /^[a-zA-Z]:[\\/]/.test(candidate) || /^\\\\/.test(candidate);
}

function buildFolderStableCommand(folderPath, folderPathBase64, maxWaitMs, intervalMs, stableMs) {
  return __buildNodeEvalCommand(FOLDER_STABLE_SCRIPT_BASE64, [
    folderPathBase64,
    String(maxWaitMs),
    String(intervalMs),
    String(stableMs),
  ]);
}

return items.map((item, index) => {
  const input = item.json || {};
  const folderPath = text(input.folderPath || input.path || input.fullPath || input.filePath);
  if (!folderPath) {
    throw new Error('setParameter: missing folderPath/path from trigger item.');
  }
  if (!text(BASE_OUTPUT_DIR)) {
    throw new Error('setParameter: BASE_OUTPUT_DIR is required.');
  }

  const folderPathBase64 = Buffer.from(folderPath, 'utf8').toString('base64');
  const folderStableMaxWaitMs = positiveInteger(input.folderStableMaxWaitMs, FOLDER_STABLE_MAX_WAIT_MS);
  const folderStableIntervalMs = positiveInteger(input.folderStableIntervalMs, FOLDER_STABLE_INTERVAL_MS);
  const folderStableStableMs = positiveInteger(input.folderStableStableMs, FOLDER_STABLE_STABLE_MS);

  return {
    json: {
      ...input,
      baseOutputDir: text(BASE_OUTPUT_DIR),
      folderPath,
      folderPathBase64,
      folderStableMaxWaitMs,
      folderStableIntervalMs,
      folderStableStableMs,
      folderStableCommand: buildFolderStableCommand(
        folderPath,
        folderPathBase64,
        folderStableMaxWaitMs,
        folderStableIntervalMs,
        folderStableStableMs,
      ),
    },
    pairedItem: item.pairedItem || { item: index },
  };
});

const current = $input.first().json || {};
const upstream = $('setParameter').first().json || {};
const stdout = String(current.stdout ?? '').trim();
const stderr = String(current.stderr ?? '').trim();
const exitCode = current.exitCode ?? 'unknown';

function parseLastJson(value) {
  if (!value) return null;
  const lines = String(value).split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    try {
      return JSON.parse(lines[i]);
    } catch (error) {}
  }
  try {
    return JSON.parse(value);
  } catch (error) {
    return null;
  }
}

function preview(value) {
  return String(value || '').replace(/\s+/g, ' ').slice(0, 500);
}

if (!stdout && !stderr) {
  throw new Error(`New folder stable check failed: Wait New Folder Stable returned empty stdout/stderr. exitCode=${exitCode}. This usually means Execute Command shell quoting or output capture failed.`);
}

const result = parseLastJson(stdout) || parseLastJson(stderr);
if (!result) {
  throw new Error(`New folder stable check failed: Wait New Folder Stable output is not valid JSON. exitCode=${exitCode}. stdout=${preview(stdout)} stderr=${preview(stderr)}`);
}

if (result.ok !== true) {
  const message = result.error || stderr || stdout || 'Wait New Folder Stable did not return ok:true.';
  const details = [
    `exitCode=${exitCode}`,
    result.waitedMs !== undefined ? `waitedMs=${result.waitedMs}` : '',
    result.fileCount !== undefined ? `fileCount=${result.fileCount}` : '',
    result.hasTempFiles !== undefined ? `hasTempFiles=${result.hasTempFiles}` : '',
  ].filter(Boolean).join(' ');
  throw new Error(`New folder stable check failed: ${message}${details ? ` (${details})` : ''}`);
}

return [{
  json: {
    ...upstream,
    folderStable: true,
    folderStableResult: result,
    folderStableWaitedMs: Number(result.waitedMs || 0),
    folderStableChecks: Number(result.checks || 0),
    folderStableFileCount: Number(result.fileCount || 0),
    folderStableTotalBytes: Number(result.totalBytes || 0),
    folderStableNewestMtimeMs: Number(result.newestMtimeMs || 0),
  },
}];

const source = $("Call 'S014-03-读取产品文件夹并标准化输入'").first().json || {};
const uploadedItems = $input.all();

function cleanString(value) {
  return String(value ?? '').trim();
}

function requiredPositiveInteger(name, value) {
  const numberValue = Number(value);
  if (!Number.isInteger(numberValue) || numberValue <= 0) {
    throw new Error(name + ' must be a positive integer, received: ' + String(value ?? ''));
  }
  return numberValue;
}

function baseName(value) {
  return cleanString(value).replace(/\\/g, '/').split('/').filter(Boolean).pop() || '';
}

function isHttpUrl(value) {
  return /^https?:\/\//i.test(cleanString(value));
}

const sourcePaths = Array.isArray(source.viewImages) && source.viewImages.length
  ? source.viewImages.map(cleanString).filter(Boolean)
  : [source.viewImageAdd1, source.viewImageAdd2, source.viewImageAdd3, source.viewImageAdd4, source.viewImageAdd5]
      .map(cleanString)
      .filter(Boolean);

if (sourcePaths.length < 3 || sourcePaths.length > 5) {
  throw new Error('S014 must return 3-5 source image paths, received ' + sourcePaths.length);
}
if (uploadedItems.length !== sourcePaths.length) {
  throw new Error('SiliconFlow upload count mismatch: expected ' + sourcePaths.length + ', received ' + uploadedItems.length);
}

const urlsByIndex = new Map();
for (const [position, item] of uploadedItems.entries()) {
  const row = item.json || {};
  const inputIndex = Number(row.inputIndex);
  const sourceFileName = cleanString(row.sourceFileName);
  const url = cleanString(row.url);
  if (!Number.isInteger(inputIndex) || inputIndex < 0 || inputIndex >= sourcePaths.length) {
    throw new Error('Invalid SiliconFlow inputIndex at result ' + (position + 1) + ': ' + row.inputIndex);
  }
  if (urlsByIndex.has(inputIndex)) throw new Error('Duplicate SiliconFlow inputIndex: ' + inputIndex);
  const expectedFileName = baseName(sourcePaths[inputIndex]);
  if (!sourceFileName || sourceFileName !== expectedFileName) {
    throw new Error('SiliconFlow filename mismatch at inputIndex ' + inputIndex + ': expected ' + expectedFileName + ', received ' + (sourceFileName || '(empty)'));
  }
  if (!isHttpUrl(url)) throw new Error('SiliconFlow URL is missing or invalid for ' + expectedFileName);
  urlsByIndex.set(inputIndex, url);
}

const viewImages = sourcePaths.map((filePath, index) => {
  const url = urlsByIndex.get(index);
  if (!url) throw new Error('Missing SiliconFlow URL for ' + baseName(filePath));
  return url;
});

const titleLength = requiredPositiveInteger('titleLength/titleLenth', source.titleLength ?? source.titleLenth);
const titleDescriptionLength = requiredPositiveInteger('titleDescriptionLength/titleDescriptionLenth', source.titleDescriptionLength ?? source.titleDescriptionLenth);

return [{
  json: {
    ...source,
    titleLength,
    titleDescriptionLength,
    titleLenth: titleLength,
    titleDescriptionLenth: titleDescriptionLength,
    sourceViewImages: sourcePaths,
    viewImages,
    imageCount: viewImages.length,
    viewImageAdd1: viewImages[0] || '',
    viewImageAdd2: viewImages[1] || '',
    viewImageAdd3: viewImages[2] || '',
    viewImageAdd4: viewImages[3] || '',
    viewImageAdd5: viewImages[4] || '',
  },
}];
